//! Schema export determinism and consistency of `schemas/public-api/` with the Rust
//! model (plan section 7.4; ADR-0006 section 9).
//!
//! The checked-in files are generated by `heimdall schema export`; these tests render
//! the same documents in-process (same formatting rule as the CLI: pretty JSON plus a
//! trailing newline) and compare. `tools/validation/check.sh` additionally runs the
//! real binary twice and diffs both runs against the checked-in directory.

use std::collections::BTreeSet;

use serde_json::Value;

use heimdall_contract::code::Code;
use heimdall_contract::schema::{code_table, public_schemas};

use crate::{assert_clean, repo_root};

/// `(file name, bytes)` for every exported document, in export order.
fn render_all() -> Vec<(String, String)> {
    let mut out = Vec::new();
    for s in public_schemas() {
        let mut text = serde_json::to_string_pretty(&s.schema).unwrap();
        text.push('\n');
        out.push((format!("{}.schema.json", s.name), text));
    }
    let mut codes = serde_json::to_string_pretty(&code_table()).unwrap();
    codes.push('\n');
    out.push(("codes.json".to_owned(), codes));
    out
}

#[test]
fn export_is_byte_identical_across_runs() {
    let first = render_all();
    for _ in 0..3 {
        assert_eq!(render_all(), first);
    }
    // Stable, unique file names.
    let names: BTreeSet<&String> = first.iter().map(|(n, _)| n).collect();
    assert_eq!(names.len(), first.len());
    for (name, text) in &first {
        assert_clean(name, text);
        assert!(text.ends_with("}\n"), "{name}: single trailing newline");
        assert!(!text.contains('\r'), "{name}: LF line endings only");
    }
}

#[test]
fn checked_in_public_api_matches_the_model_exactly() {
    let dir = repo_root().join("schemas/public-api");
    let rendered = render_all();
    for (name, expected) in &rendered {
        let actual = std::fs::read_to_string(dir.join(name))
            .unwrap_or_else(|e| panic!("{name} missing from schemas/public-api: {}", e.kind()));
        assert!(
            &actual == expected,
            "{name} is stale: run `heimdall schema export` and commit the result"
        );
    }
    let on_disk: BTreeSet<String> = std::fs::read_dir(&dir)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    let expected: BTreeSet<String> = rendered.into_iter().map(|(n, _)| n).collect();
    assert_eq!(
        on_disk, expected,
        "unexpected or missing files in schemas/public-api"
    );
}

#[test]
fn code_schema_enumerates_exactly_the_code_table() {
    let schema = serde_json::to_value(
        public_schemas()
            .into_iter()
            .find(|s| s.name == "code")
            .unwrap()
            .schema,
    )
    .unwrap();
    let from_schema: Vec<&str> = schema["oneOf"]
        .as_array()
        .unwrap()
        .iter()
        .map(|alt| alt["const"].as_str().unwrap())
        .collect();
    let from_model: Vec<&str> = Code::all().iter().map(|c| c.as_str()).collect();
    assert_eq!(from_schema, from_model);
}

#[test]
fn codes_json_rows_equal_the_model_and_golden() {
    let golden: Value = serde_json::from_str(
        &std::fs::read_to_string(repo_root().join("tests/contracts/golden/code-table.golden.json"))
            .unwrap(),
    )
    .unwrap();
    let checked_in: Value = serde_json::from_str(
        &std::fs::read_to_string(repo_root().join("schemas/public-api/codes.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(checked_in["schema_version"], "1");
    let rows = checked_in["codes"].as_array().unwrap();
    let grows = golden["rows"].as_array().unwrap();
    assert_eq!(
        rows.len(),
        30,
        "ADR-0006 section 5 has 30 rows (revision 3)"
    );
    assert_eq!(rows.len(), grows.len());
    for (row, g) in rows.iter().zip(grows) {
        assert_eq!(row["code"], g["code"]);
        assert_eq!(row["exit_code"], g["exit"]);
        assert_eq!(row["retryable"], g["retryable"]);
        assert_eq!(row["default_effect_status"], g["effect"]);
        assert_eq!(row["default_next_action"], g["next"]);
        assert_eq!(row["success"], Value::Bool(g["exit"] == 0));
    }
}

#[test]
fn every_schema_is_a_closed_set_of_supported_keywords() {
    // Every exported schema must be fully checkable by the in-tree validator: if a
    // schema starts using a keyword the validator does not know, example validation
    // would silently weaken. Walk each document and collect the keywords.
    const KNOWN: &[&str] = &[
        "$schema",
        "$defs",
        "$ref",
        "title",
        "description",
        "default",
        "format",
        "type",
        "const",
        "enum",
        "minimum",
        "maximum",
        "properties",
        "required",
        "items",
        "prefixItems",
        "minItems",
        "maxItems",
        "uniqueItems",
        "anyOf",
        "oneOf",
        "allOf",
    ];
    fn walk(v: &Value, in_properties: bool, found: &mut BTreeSet<String>) {
        match v {
            Value::Object(map) => {
                for (k, child) in map {
                    if !in_properties {
                        found.insert(k.clone());
                    }
                    // Values of these keywords are data, not subschemas.
                    if matches!(k.as_str(), "default" | "examples" | "const" | "enum") {
                        continue;
                    }
                    // Members of `properties` and `$defs` are names, not keywords.
                    walk(child, k == "properties" || k == "$defs", found);
                }
            }
            Value::Array(items) => items.iter().for_each(|i| walk(i, false, found)),
            _ => {}
        }
    }
    for s in public_schemas() {
        let doc = serde_json::to_value(&s.schema).unwrap();
        let mut found = BTreeSet::new();
        walk(&doc, false, &mut found);
        for k in &found {
            assert!(KNOWN.contains(&k.as_str()), "{}: keyword `{k}`", s.name);
        }
    }
}

#[test]
fn schema_ids_are_never_secret_bearing_formats() {
    // IDs are opaque references (spec section 11.2): the schemas type them as plain
    // strings and none declares a `password`/`byte`-style format.
    for (name, text) in render_all() {
        assert!(!text.contains("\"format\": \"password\""), "{name}");
        assert!(!text.contains("\"format\": \"byte\""), "{name}");
    }
}

/// Wave-1 E5: every envelope schema (top-level documents and envelope definitions
/// embedded in other documents, e.g. IPC `reject`/`response`) lists `warnings` and
/// `next` as required, because writers always emit them.
#[test]
fn envelope_schemas_require_warnings_and_next() {
    fn requires(schema: &Value, field: &str) -> bool {
        schema["required"]
            .as_array()
            .is_some_and(|r| r.iter().any(|f| f == field))
    }
    let mut checked = 0;
    for s in public_schemas() {
        let doc = serde_json::to_value(&s.schema).unwrap();
        if s.name == "envelope" || s.name.starts_with("envelope.") {
            for field in [
                "schema_version",
                "state",
                "code",
                "data",
                "warnings",
                "next",
            ] {
                assert!(requires(&doc, field), "{}: `{field}` not required", s.name);
            }
            assert!(
                !requires(&doc, "operation_id"),
                "{}: operation_id is optional",
                s.name
            );
            checked += 1;
        }
        if let Some(defs) = doc["$defs"].as_object() {
            for (name, def) in defs {
                if name.starts_with("Envelope") {
                    for field in ["warnings", "next"] {
                        assert!(requires(def, field), "{}#{name}: `{field}`", s.name);
                    }
                    checked += 1;
                }
            }
        }
    }
    assert!(checked >= 6, "envelope schemas found: {checked}");
}

/// Wave-1 E5, reader side: the schema describes what writers emit; a lenient reader
/// still accepts an envelope that omits `warnings` and `next` (as empty and `null`)
/// and materializes both when it writes the document back.
#[test]
fn envelope_without_warnings_and_next_still_deserializes() {
    use heimdall_contract::envelope::{Envelope, ErrorData};
    let bare = r#"{"schema_version":"1","state":"succeeded","code":"OK","data":{"k":1}}"#;
    let env: Envelope<Value> = serde_json::from_str(bare).unwrap();
    assert!(env.warnings.is_empty());
    assert!(env.next.is_none());
    let written = serde_json::to_value(&env).unwrap();
    assert_eq!(written["warnings"], serde_json::json!([]));
    assert!(written.get("next").is_some_and(Value::is_null));

    let bare_error = r#"{"schema_version":"1","state":"failed","code":"USAGE_ERROR","data":{"error":{"code":"USAGE_ERROR","effect_status":"none","retryable":false,"next":{"action":"fix_request"},"message":"m"}}}"#;
    let err: Envelope<ErrorData> = serde_json::from_str(bare_error).unwrap();
    assert!(err.warnings.is_empty() && err.next.is_none());
    assert_eq!(err.code, Code::UsageError);
}
